\set ON_ERROR_STOP on
create function pg_temp.check_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if;raise notice 'PASS: %',label;end;$$;
create function pg_temp.expect_error(command text,expected text,label text) returns void language plpgsql as $$begin begin execute command; exception when others then if sqlstate<>expected then raise exception 'FAIL: % expected % got % (%)',label,expected,sqlstate,sqlerrm; end if;raise notice 'PASS: %',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end;$$;
insert into auth.users(id,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,now() from generate_series(201,205)n;
insert into public.tenants(id,name) values('50000000-0000-0000-0000-000000000001','Rota synthetic A'),('50000000-0000-0000-0000-000000000002','Rota synthetic B');
insert into public.tenant_memberships(tenant_id,user_id,display_name,role) select '50000000-0000-0000-0000-000000000001',('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic '||n,case n when 201 then 'owner' when 202 then 'manager' else 'employee' end from generate_series(201,204)n;
insert into public.tenant_memberships(tenant_id,user_id,display_name,role) values('50000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000205','Foreign owner','owner');
insert into public.agents(tenant_id,user_id,first_name,last_name,phone,created_by) select '50000000-0000-0000-0000-000000000001',('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic',n::text,'+447700900'||n,'00000000-0000-0000-0000-000000000201' from generate_series(201,204)n;
insert into public.agents(tenant_id,user_id,first_name,last_name,phone,created_by) values('50000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000205','Foreign','Synthetic','+447700900205','00000000-0000-0000-0000-000000000205');
do $$declare tbl text;op text;begin foreach tbl in array array['rota_schedules','rota_admins','rota_agents','rota_jobs','rota_shifts','rota_audit'] loop perform pg_temp.check_true((select relrowsecurity from pg_class where oid=('public.'||tbl)::regclass),'RLS on '||tbl);foreach op in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE'] loop perform pg_temp.check_true(not has_table_privilege('anon','public.'||tbl,op),'anon denied '||op||' '||tbl);if op<>'SELECT' then perform pg_temp.check_true(not has_table_privilege('authenticated','public.'||tbl,op),'direct write denied '||op||' '||tbl);end if;end loop;end loop;end;$$;
select pg_temp.check_true(not has_function_privilege('anon','public.save_rota(uuid,jsonb)','execute'),'anon cannot mutate');
select pg_temp.check_true((select proconfig @> array['search_path=""'] from pg_proc where oid='workforce_private.save_rota(uuid,jsonb)'::regprocedure),'fixed definer search path');
create function pg_temp.create_schedule(n text) returns jsonb language sql as $$select public.save_rota('50000000-0000-0000-0000-000000000001',jsonb_build_object('action','create_schedule','name',n,'time_zone','Europe/London','agent_ids',(select jsonb_agg(id) from public.agents where tenant_id='50000000-0000-0000-0000-000000000001'),'admin_ids',jsonb_build_array('00000000-0000-0000-0000-000000000202')))$$;
create function pg_temp.change(c jsonb,n text default 'Main') returns jsonb language sql as $$select public.save_rota('50000000-0000-0000-0000-000000000001', c||jsonb_build_object('schedule_id',(select id from public.rota_schedules where name=n),'revision',(select revision from public.rota_schedules where name=n)))$$;
create function pg_temp.shift(start_at text,end_at text,allow_it boolean default false) returns jsonb language sql as $$select pg_temp.change(jsonb_build_object('action','save_shift','agent_id',(select id from public.agents where phone='+447700900203'),'job_id',(select id from public.rota_jobs where name='Care'),'starts_at',start_at,'ends_at',end_at,'allow_overlap',allow_it))$$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000201',false);
select pg_temp.create_schedule('Main');select pg_temp.create_schedule('Race');select pg_temp.create_schedule('Race two');
select pg_temp.change('{"action":"add_job","name":"Care","color":"#285c4c"}');
select pg_temp.change('{"action":"add_job","name":"Race","color":"#123456"}','Race');
select pg_temp.change('{"action":"add_job","name":"Race two","color":"#123456"}','Race two');
-- Leave Race at revision 1 for deterministic concurrency check.
reset role; update public.rota_schedules set revision=1 where name='Race'; set role authenticated;
select pg_temp.expect_error($q$select public.save_rota('50000000-0000-0000-0000-000000000002','{"action":"create_schedule","name":"Foreign","time_zone":"UTC","agent_ids":[],"admin_ids":[]}')$q$,'42501','foreign tenant mutation denied');
select pg_temp.expect_error($q$select pg_temp.change('{"action":"add_job","name":"Bad","color":"url(x)"}')$q$,'23514','color CSS injection denied');
select pg_temp.expect_error($q$select pg_temp.change('{"action":"add_job","name":"Fake","color":"#123456","role":"owner"}')$q$,'22023','unknown fields denied');
select pg_temp.shift('2026-10-24T22:00:00Z','2026-10-25T07:00:00Z');
select pg_temp.check_true((select ends_at-starts_at=interval '9 hours' from public.rota_shifts),'overnight DST fallback retains actual nine elapsed hours');
select pg_temp.expect_error($q$select pg_temp.shift('2026-10-25T06:00:00Z','2026-10-25T10:00:00Z')$q$,'P0001','overlap warning requires acknowledgement');
select pg_temp.shift('2026-10-25T07:00:00Z','2026-10-25T10:00:00Z');
select pg_temp.check_true((select count(*)=2 from public.rota_shifts),'adjacent shifts accepted');
select pg_temp.shift('2026-10-25T08:00:00Z','2026-10-25T11:00:00Z',true);
select pg_temp.check_true((select count(*)=3 from public.rota_shifts),'explicit overlap acknowledged');
select pg_temp.expect_error($q$select pg_temp.shift('2026-10-26T10:00','2026-10-26T14:00')$q$,'22023','offset-free timestamp denied');
select pg_temp.expect_error($q$select pg_temp.shift('2026-10-26T10:00:00Z','2026-10-26T09:00:00Z')$q$,'23514','negative duration denied');
select pg_temp.expect_error($q$select pg_temp.shift('2026-10-26T10:00:00Z','2026-10-27T11:00:00Z')$q$,'23514','more than 24 elapsed hours denied');
select pg_temp.expect_error($q$select public.save_rota('50000000-0000-0000-0000-000000000001',jsonb_build_object('action','add_job','schedule_id',(select id from public.rota_schedules where name='Main'),'revision',1,'name','Stale','color','#123456'))$q$,'40001','stale schedule version denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000203',false);
select pg_temp.check_true((select count(*)=0 from public.rota_shifts),'employees cannot read drafts');
select pg_temp.check_true((select count(*)=0 from public.rota_admins),'employees cannot read separate administrators');
select pg_temp.check_true((select count(*)=3 from public.rota_agents),'employee sees own assignment in each schedule only');
select pg_temp.expect_error($q$select pg_temp.change('{"action":"publish"}')$q$,'42501','employee cannot publish');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000202',false);
select pg_temp.change('{"action":"publish"}');
select pg_temp.check_true((select count(*)=3 from public.rota_shifts where status='published' and published_at is not null),'named manager can publish drafts atomically');
select pg_temp.expect_error($q$select pg_temp.create_schedule('Manager creates')$q$,'42501','manager cannot create global schedules');
select pg_temp.expect_error($q$select pg_temp.change('{"action":"archive"}')$q$,'42501','manager cannot archive');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000203',false);
select pg_temp.check_true((select count(*)=3 from public.rota_shifts),'employee reads own published shifts');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000204',false);
select pg_temp.check_true((select count(*)=0 from public.rota_shifts),'coworker cannot read another employee published shifts');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000205',false);
select pg_temp.check_true((select count(*)=0 from public.rota_schedules) and (select count(*)=0 from public.rota_jobs) and (select count(*)=0 from public.rota_shifts),'foreign tenant reads isolated');
reset role;
select pg_temp.expect_error($q$insert into public.rota_agents select '50000000-0000-0000-0000-000000000001',(select id from public.rota_schedules where name='Main'),(select id from public.agents where phone='+447700900205')$q$,'23503','tenant-bound assignment FK rejects cross-company agent');
update public.tenant_memberships set role='manager' where user_id='00000000-0000-0000-0000-000000000204';
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000204',false);
select pg_temp.expect_error($q$select pg_temp.change('{"action":"add_job","name":"No grant","color":"#123456"}')$q$,'42501','manager without named schedule grant cannot write');
reset role;update public.tenant_memberships set status='suspended' where user_id='00000000-0000-0000-0000-000000000202';
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000202',false);
select pg_temp.check_true((select count(*)=0 from public.rota_schedules),'suspension hides schedules');
select pg_temp.expect_error($q$select pg_temp.change('{"action":"publish"}')$q$,'42501','suspension denies writes with existing identity');
reset role;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000201',false);
select pg_temp.expect_error(format($q$select pg_temp.change('{"action":"save_shift","id":"%s","agent_id":"%s","job_id":"%s","starts_at":"2026-10-24T22:00:00Z","ends_at":"2026-10-25T07:00:00Z","title":"Changed"}')$q$,(select id from public.rota_shifts limit 1),(select id from public.agents where phone='+447700900203'),(select id from public.rota_jobs where name='Care')),'22023','published shift cannot accidentally be returned to draft');
select pg_temp.shift('2026-12-01T09:00:00Z','2026-12-01T17:00:00Z');
reset role;update public.tenant_memberships set status='suspended' where user_id='00000000-0000-0000-0000-000000000203';
set role authenticated;select pg_temp.expect_error($q$select pg_temp.change('{"action":"publish"}')$q$,'22023','publishing rejects suspended employee');
select pg_temp.check_true((select count(*)=1 from public.rota_shifts where status='draft'),'failed publication preserves drafts atomically');
reset role;update public.tenant_memberships set status='active' where user_id='00000000-0000-0000-0000-000000000203';
set role authenticated;select pg_temp.change('{"action":"archive"}');select pg_temp.expect_error($q$select pg_temp.change('{"action":"publish"}')$q$,'22023','archived schedule cannot publish');
select pg_temp.change('{"action":"restore"}');select pg_temp.change('{"action":"publish"}');
select pg_temp.check_true((select count(*)=4 from public.rota_shifts where status='published'),'restoring allows remaining drafts to publish');
reset role;update public.tenant_memberships set status='active' where user_id='00000000-0000-0000-0000-000000000202';
